import unittest

from solucao import juntar


class TestJuntarDicionarios(unittest.TestCase):
    def test_junta_as_chaves_novas(self):
        """juntar acrescenta as chaves do segundo dicionario"""
        d = {"a": 1}
        juntar(d, {"b": 2})
        self.assertEqual(d, {"a": 1, "b": 2})

    def test_chave_repetida_fica_com_o_valor_novo(self):
        """juntar troca o valor das chaves repetidas"""
        d = {"a": 1}
        juntar(d, {"a": 9})
        self.assertEqual(d, {"a": 9})

    def test_junta_com_o_dicionario_vazio(self):
        """juntar com o dicionario vazio nao muda nada"""
        d = {"a": 1}
        juntar(d, {})
        self.assertEqual(d, {"a": 1})
